/**
 * Speech lexicon (task 9.2, Requirements 12.8, 14.5). The set of words the small English Vosk
 * model can recognise. Pure: no file or network access.
 *
 * The full word list is generated by `tools/build-lexicon.ts` into `public/vosk/lexicon.txt`
 * (about 152,000 words read from the model's embedded symbol table). A runtime adapter loads that
 * text and calls `parseLexiconText`. Until then `FALLBACK_LEXICON` stands in. It is a hand-curated
 * stub that covers the fixed command phrases, numbers, and common device names, so an unloaded
 * list flags unusual names (the safe direction) and never lets an unknown word through.
 */

export interface Lexicon {
  /** Case-insensitive membership test. */
  has(word: string): boolean;
  readonly size: number;
}

/** Build a lexicon from words. Entries are trimmed and lowercased, empty entries are dropped. */
export function createLexicon(words: Iterable<string>): Lexicon {
  const set = new Set<string>();
  for (const word of words) {
    const clean = word.trim().toLowerCase();
    if (clean.length > 0) set.add(clean);
  }
  return {
    has: (word) => set.has(word.trim().toLowerCase()),
    size: set.size,
  };
}

/** Parse the generated `lexicon.txt` (one word per line). */
export function parseLexiconText(text: string): Lexicon {
  return createLexicon(text.split(/\r?\n/));
}

/**
 * Words of `phrase` (split on whitespace, lowercased) that are not in the lexicon, in order and
 * without repeats. An empty result means every word is recognisable.
 */
export function findOutOfLexicon(lexicon: Lexicon, phrase: string): string[] {
  const missing: string[] = [];
  for (const raw of phrase.toLowerCase().split(/\s+/)) {
    if (raw.length === 0 || lexicon.has(raw) || missing.includes(raw)) continue;
    missing.push(raw);
  }
  return missing;
}

const FALLBACK_WORDS = `
a an the my this that it one is
turn switch on off dim brighten set to color colour come here sit look at point remember as timer for
minutes minute go away stop yes no okay hello hey capri
zero one two three four five six seven eight nine ten eleven twelve thirteen fourteen fifteen
sixteen seventeen eighteen nineteen twenty thirty forty fifty sixty seventy eighty ninety hundred
thousand first second third fourth fifth sixth seventh eighth ninth tenth
red orange yellow green blue purple pink white warm cool
lamp lamps light lights bulb bulbs strip lantern chandelier sconce
desk floor ceiling bedside corner table couch sofa bed wall shelf window door
kitchen living room bedroom bathroom hall hallway office garage porch garden study dining
main top bottom left right front back side center middle upper lower big small little
reading night mood ambient accent night
and or of in by with
`;

/** Curated stand-in used until the generated word list is loaded. Not the real vocabulary. */
export const FALLBACK_LEXICON: Lexicon = createLexicon(FALLBACK_WORDS.split(/\s+/));
